#!/usr/bin/env node
/**
 * Compile packages/domain/src/promotion.cases.json into a SQL suite that runs
 * the same cases through app.evaluate_promotion's rule evaluator.
 *
 * The point is that the fixture is written once. The TypeScript side reads the
 * JSON directly (promotion.parity.test.ts); this generates the Postgres side.
 * Neither can be quietly edited to agree with a broken implementation.
 *
 *   node scripts/gen-promotion-parity.mjs
 *
 * `npm run verify` checks the generated file is current, the same way it does
 * for the attendance parity suite.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const SRC = join(ROOT, 'packages', 'domain', 'src', 'promotion.cases.json')
const OUT = join(ROOT, 'supabase', 'tests', '_generated_promotion_parity.sql')

const spec = JSON.parse(readFileSync(SRC, 'utf8'))
const lit = (o) => `'${JSON.stringify(o).replace(/'/g, "''")}'::jsonb`

const rows = spec.cases.map((c) => {
  const facts = { ...spec.factDefaults, ...c.facts }
  return `  (${lit(c.name)}::text, ${lit(facts)}, ${lit(c.expect)}::text)`
    .replace(/'"([^"]*)"'::text/g, "'$1'::text")
})

const sql = `-- GENERATED by scripts/gen-promotion-parity.mjs — do not edit.
-- Source of truth: packages/domain/src/promotion.cases.json
--
-- Runs the shared promotion fixture through the Postgres evaluator. The same
-- cases run through the TypeScript evaluator in
-- packages/domain/src/promotion.parity.test.ts. Both must agree: the engine
-- decides which children move up a year, and an implementation that disagrees
-- with itself is worse than one that is simply wrong, because it is wrong only
-- sometimes.
--
-- ${spec.cases.length} cases.

create temp table if not exists promo_parity(
  case_name text, facts jsonb, expected text, actual text, verdict text);
truncate promo_parity;

insert into promo_parity (case_name, facts, expected) values
${rows.join(',\n')};

-- Evaluate each fixture against the seeded rules for the demo school's active
-- year, which app.seed_promotion_rules populated.
do $$
declare
  v_year uuid; c record; r record; cond jsonb; all_hold boolean; v_outcome text;
begin
  select y.id into v_year
  from academic_year y join school s on s.id = y.school_id
  where s.code = 'DEMO-SSS' and y.status = 'active'
  limit 1;

  if v_year is null then
    select y.id into v_year from academic_year y
    join school s on s.id = y.school_id where s.code = 'DEMO-SSS'
    order by y.starts_on desc limit 1;
  end if;

  for c in select * from promo_parity loop
    v_outcome := null;

    for r in
      select pr.* from promotion_rule pr
      where pr.academic_year_id = v_year
        and pr.is_active
        and pr.grade = (c.facts ->> 'grade')::smallint
        and (pr.stream is null or pr.stream::text = (c.facts ->> 'stream'))
      order by pr.priority
    loop
      all_hold := true;
      for cond in select * from jsonb_array_elements(r.conditions) loop
        if not app.promotion_condition_holds(c.facts, cond) then
          all_hold := false;
          exit;
        end if;
      end loop;

      if all_hold then
        v_outcome := r.outcome::text;
        exit;
      end if;
    end loop;

    -- Same fall-through as app.evaluate_promotion and evaluatePromotion().
    v_outcome := coalesce(v_outcome, 'repeat');

    update promo_parity
       set actual = v_outcome,
           verdict = case when v_outcome = expected then 'ok' else 'MISMATCH' end
     where case_name = c.case_name;
  end loop;
end $$;

select case_name, expected, actual, verdict
from promo_parity order by verdict desc, case_name;

select case
         when exists (select 1 from promo_parity where verdict <> 'ok')
         then 'FAIL — Postgres and TypeScript disagree, see rows above'
         else 'PASS — ' || (select count(*) from promo_parity)::text ||
              ' cases agree across both implementations'
       end as result;
`

writeFileSync(OUT, sql, 'utf8')
console.log(`wrote ${OUT} — ${spec.cases.length} cases`)
